# ctrl32 telemetry - setup of a kiosk PC for displays (spec 034). Generated by the server for the kiosk PC
# '__CTRL32_NAME__'; it carries this PC's credential: keep the file private and delete it after the setup.
#
# Run once in an elevated PowerShell (Run as administrator) on the Windows 10/11 PC behind the displays:
#   powershell -ExecutionPolicy Bypass -File .\setup-kiosk-__CTRL32_SHORT__.ps1 [-KioskUser kiosk] [-ProfileDir <dir>]
# It is safe to run again. What it does:
#   - a standard user for the kiosk (created if missing) that signs in automatically; its password stays on this PC
#     (an LSA secret) and is never sent anywhere
#   - power: never sleep or blank; no lock screen, notifications, tips; Windows Update installs and restarts at 03:00
#   - Chrome policies for unattended video (autoplay, no sign-in, no translation, hardware decoding)
#   - C:\ProgramData\ctrl32-kiosk: the launcher (one Chrome kiosk per monitor, each its own display; started again
#     when it closes) and the agent (reports to the server, performs the operations of the Displays screen)
#   - the scheduled tasks "ctrl32 kiosk launcher" (at the kiosk user's logon) and "ctrl32 kiosk agent" (SYSTEM)
# Parameters:
#   -KioskUser       the kiosk account (default: kiosk); an existing account with automatic logon is kept as it is
#   -ResetPassword   give the kiosk account a new random password (and automatic logon with it)
#   -ProfileDir      where the Chrome profiles of the monitors live (profile-0, profile-1, ...): keep the profiles of an
#                    older setup so its displays stay paired
#   -ReplaceTask     the name of an older launcher task to switch off (it is disabled, not deleted)
#   -NoReboot        do not offer the restart at the end
param(
    [string]$KioskUser = 'kiosk',
    [switch]$ResetPassword,
    [string]$ProfileDir = '',
    [string]$ReplaceTask = '',
    [switch]$NoReboot
)
$ErrorActionPreference = 'Stop'
$Server = '__CTRL32_SERVER__'
$Token = '__CTRL32_TOKEN__'
$KioskId = '__CTRL32_KIOSK_ID__'
$base = 'C:\ProgramData\ctrl32-kiosk'
$udir = Join-Path $base 'user'
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

$me = [Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
if (-not $me.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { throw 'Run this script in an elevated PowerShell (Run as administrator).' }
function Step($m) { Write-Host "== $m" -ForegroundColor Cyan }
function Reg($path, $name, $value, $type = 'DWord') {
    if (-not (Test-Path $path)) { New-Item -Path $path -Force | Out-Null }
    New-ItemProperty -Path $path -Name $name -Value $value -PropertyType $type -Force | Out-Null
}

Step "server $Server"
$headers = @{ 'X-Kiosk-Token' = $Token }
try { $scripts = Invoke-RestMethod -Method Get -Uri ($Server + '/api/v1/kiosk/scripts') -Headers $headers -TimeoutSec 30 -UseBasicParsing }
catch { throw "The server $Server does not answer this PC ($($_.Exception.Message)). Check the address and the network, or create a new setup script (the credential may have been replaced)." }

Step 'folders'
New-Item -ItemType Directory -Force -Path $base, $udir | Out-Null
# the scripts run as SYSTEM: only SYSTEM and administrators may change them; the kiosk user writes only into user\
& icacls $base /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' '*S-1-5-32-545:(OI)(CI)RX' | Out-Null

Step "kiosk user $KioskUser"
$wl = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'
$auto = (Get-ItemProperty $wl -ErrorAction SilentlyContinue)
$keep = (Get-LocalUser -Name $KioskUser -ErrorAction SilentlyContinue) -and $auto.AutoAdminLogon -eq '1' -and $auto.DefaultUserName -eq $KioskUser -and -not $ResetPassword
if ($keep) { Write-Host "the account exists and signs in automatically: kept as it is" }
else {
    $chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789'
    $rng = [Security.Cryptography.RandomNumberGenerator]::Create(); $buf = New-Object byte[] 24; $rng.GetBytes($buf)
    $pw = -join ($buf | ForEach-Object { $chars[$_ % $chars.Length] })
    $sec = ConvertTo-SecureString $pw -AsPlainText -Force
    if (Get-LocalUser -Name $KioskUser -ErrorAction SilentlyContinue) { Set-LocalUser -Name $KioskUser -Password $sec -PasswordNeverExpires $true }
    else {
        New-LocalUser -Name $KioskUser -Password $sec -FullName 'ctrl32 kiosk' -Description 'ctrl32 telemetry displays' -PasswordNeverExpires -UserMayNotChangePassword | Out-Null
        Add-LocalGroupMember -SID 'S-1-5-32-545' -Member $KioskUser
    }
    Add-Type -TypeDefinition @'
using System; using System.Runtime.InteropServices;
public static class Ctrl32Lsa {
  [StructLayout(LayoutKind.Sequential)] struct LSA_UNICODE_STRING { public ushort Length, MaximumLength; public IntPtr Buffer; }
  [StructLayout(LayoutKind.Sequential)] struct LSA_OBJECT_ATTRIBUTES { public int Length; public IntPtr RootDirectory, ObjectName; public int Attributes; public IntPtr SecurityDescriptor, SecurityQualityOfService; }
  [DllImport("advapi32.dll")] static extern uint LsaOpenPolicy(IntPtr s, ref LSA_OBJECT_ATTRIBUTES a, int access, out IntPtr h);
  [DllImport("advapi32.dll")] static extern uint LsaStorePrivateData(IntPtr h, ref LSA_UNICODE_STRING k, ref LSA_UNICODE_STRING d);
  [DllImport("advapi32.dll")] static extern uint LsaClose(IntPtr h);
  static LSA_UNICODE_STRING S(string v) { var u = new LSA_UNICODE_STRING(); u.Buffer = Marshal.StringToHGlobalUni(v); u.Length = (ushort)(v.Length * 2); u.MaximumLength = (ushort)(v.Length * 2 + 2); return u; }
  public static uint Store(string key, string val) { var a = new LSA_OBJECT_ATTRIBUTES(); IntPtr h; uint r = LsaOpenPolicy(IntPtr.Zero, ref a, 0x00000020 | 0x00000004, out h); if (r != 0) return r; var k = S(key); var d = S(val); r = LsaStorePrivateData(h, ref k, ref d); LsaClose(h); return r; }
}
'@
    # automatic logon with the password as an LSA secret (not in the registry)
    if ([Ctrl32Lsa]::Store('DefaultPassword', $pw) -ne 0) { throw 'the password for the automatic logon could not be stored' }
    Reg $wl 'AutoAdminLogon' '1' 'String'
    Reg $wl 'DefaultUserName' $KioskUser 'String'
    Reg $wl 'DefaultDomainName' $env:COMPUTERNAME 'String'
    Remove-ItemProperty -Path $wl -Name 'DefaultPassword' -ErrorAction SilentlyContinue
    Remove-ItemProperty -Path $wl -Name 'AutoLogonCount' -ErrorAction SilentlyContinue
    # Windows 11 hides the password logon when Windows Hello is preferred; the automatic logon needs it
    Reg 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\PasswordLess\Device' 'DevicePasswordLessBuildVersion' 0
    $pw = $null
    Write-Host "automatic logon of $KioskUser set (the password is not shown and not kept anywhere else)"
}
& icacls $udir /grant "${KioskUser}:(OI)(CI)M" | Out-Null
if ($ProfileDir) {
    New-Item -ItemType Directory -Force -Path $ProfileDir | Out-Null
    & icacls $ProfileDir /grant "${KioskUser}:(OI)(CI)M" | Out-Null
}

Step 'power, lock screen, notifications'
$ErrorActionPreference = 'Continue'
powercfg /setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c 2>$null   # high performance (when the PC has it)
foreach ($s in 'monitor-timeout-ac', 'standby-timeout-ac', 'hibernate-timeout-ac', 'disk-timeout-ac') { powercfg /change $s 0 }
powercfg /hibernate off
Reg 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' 'HiberbootEnabled' 0
powercfg /setacvalueindex SCHEME_CURRENT 2a737441-1930-4402-8d77-b2bebba308a3 48e6b7a6-50f5-4782-a5d4-53bb8f07e226 0   # USB selective suspend off
powercfg /setacvalueindex SCHEME_CURRENT 501a4d13-42af-4429-9fd1-a8218c268e20 ee12f906-d277-404b-b6da-e5fa1a576df5 0   # PCIe link power saving off
powercfg /setactive SCHEME_CURRENT
Get-NetAdapter -Physical -ErrorAction SilentlyContinue | ForEach-Object { Disable-NetAdapterPowerManagement -Name $_.Name -ErrorAction SilentlyContinue }
Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Personalization' 'NoLockScreen' 1
Reg 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'InactivityTimeoutSecs' 0
Reg 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'EnableFirstLogonAnimation' 0
Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' 'DisableWindowsConsumerFeatures' 1
Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' 'DisableSoftLanding' 1
Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\OOBE' 'DisablePrivacyExperience' 1
Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Explorer' 'DisableNotificationCenter' 1
Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CurrentVersion\PushNotifications' 'NoToastApplicationNotification' 1
Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Error Reporting' 'DontShowUI' 1
Reg 'HKLM:\SOFTWARE\Microsoft\Windows\Windows Error Reporting' 'DontShowUI' 1
Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender Security Center\Notifications' 'DisableEnhancedNotifications' 1
Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsCopilot' 'TurnOffWindowsCopilot' 1
Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Dsh' 'AllowNewsAndInterests' 0
Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Control Panel\Desktop' 'ScreenSaveActive' '0' 'String'

Step 'Windows Update: install and restart at 03:00, never ask on the screen'
$wu = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
Reg "$wu\AU" 'NoAutoUpdate' 0
Reg "$wu\AU" 'AUOptions' 4
Reg "$wu\AU" 'ScheduledInstallDay' 0
Reg "$wu\AU" 'ScheduledInstallTime' 3
Reg "$wu\AU" 'AlwaysAutoRebootAtScheduledTime' 1
Reg "$wu\AU" 'AlwaysAutoRebootAtScheduledTimeMinutes' 15
Reg $wu 'SetAutoRestartNotificationDisable' 1
Reg $wu 'SetUpdateNotificationLevel' 1
Reg $wu 'UpdateNotificationLevel' 2
Reg $wu 'SetActiveHours' 1
Reg $wu 'ActiveHoursStart' 6
Reg $wu 'ActiveHoursEnd' 23

Step 'Chrome and Edge policies'
foreach ($cp in 'HKLM:\SOFTWARE\Policies\Google\Chrome', 'HKLM:\SOFTWARE\Policies\Microsoft\Edge') {
    Reg $cp 'AutoplayAllowed' 1
    Reg $cp 'TranslateEnabled' 0
    Reg $cp 'PasswordManagerEnabled' 0
    Reg $cp 'BrowserSignin' 0
    Reg $cp 'SyncDisabled' 1
    Reg $cp 'DefaultBrowserSettingEnabled' 0
    Reg $cp 'MetricsReportingEnabled' 0
    Reg $cp 'BackgroundModeEnabled' 0
    Reg $cp 'HardwareAccelerationModeEnabled' 1
    Reg $cp 'PromotionsEnabled' 0
    Reg $cp 'SearchSuggestEnabled' 0
    Reg $cp 'AutofillAddressEnabled' 0
    Reg $cp 'AutofillCreditCardEnabled' 0
    Reg $cp 'DefaultNotificationsSetting' 2
    Reg $cp 'RelaunchNotification' 0
}
$ErrorActionPreference = 'Stop'

Step 'scripts and settings'
$utf8 = New-Object Text.UTF8Encoding $false
$agentJson = Join-Path $base 'agent.json'
[IO.File]::WriteAllText($agentJson, (@{ server = $Server; token = $Token; kiosk = $KioskId } | ConvertTo-Json), $utf8)
# the credential: SYSTEM and administrators only
& icacls $agentJson /inheritance:r /grant:r '*S-1-5-18:F' '*S-1-5-32-544:F' | Out-Null
$local = @{ kiosk_user = $KioskUser; profiles = $(if ($ProfileDir) { $ProfileDir } else { Join-Path $udir 'profiles' }) }
[IO.File]::WriteAllText((Join-Path $base 'local.json'), ($local | ConvertTo-Json), $utf8)
foreach ($name in 'kiosk-agent.ps1', 'kiosk-launcher.ps1', 'launcher.json') {
    $text = $scripts.files.$name
    if (-not $text) { throw "the server sent no $name" }
    [IO.File]::WriteAllText((Join-Path $base $name), $text, $utf8)
}
Remove-Item (Join-Path $base 'capture.ps1') -Force -ErrorAction SilentlyContinue   # helper of setups before 0.86.5
Set-Content (Join-Path $base 'version.txt') $scripts.version -Encoding ASCII

Step 'scheduled tasks'
if ($ReplaceTask) {
    Get-ScheduledTask -TaskName $ReplaceTask -ErrorAction SilentlyContinue | Disable-ScheduledTask | Out-Null
    Get-ScheduledTask -TaskName $ReplaceTask -ErrorAction SilentlyContinue | Stop-ScheduledTask -ErrorAction SilentlyContinue
    Write-Host "the older task '$ReplaceTask' is disabled (not deleted)"
}
$set = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit ([TimeSpan]::Zero) -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1) -MultipleInstances IgnoreNew
$ps = "-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File"
$la = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "$ps `"$base\kiosk-launcher.ps1`""
$lt = New-ScheduledTaskTrigger -AtLogOn -User "$env:COMPUTERNAME\$KioskUser"
$lp = New-ScheduledTaskPrincipal -UserId "$env:COMPUTERNAME\$KioskUser" -LogonType Interactive -RunLevel Limited
Register-ScheduledTask -TaskName 'ctrl32 kiosk launcher' -Action $la -Trigger $lt -Principal $lp -Settings $set -Force | Out-Null
$aa = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "$ps `"$base\kiosk-agent.ps1`""
$at = @((New-ScheduledTaskTrigger -AtStartup), (New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(1) -RepetitionInterval (New-TimeSpan -Minutes 5) -RepetitionDuration (New-TimeSpan -Days 3650)))
$ap = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
Register-ScheduledTask -TaskName 'ctrl32 kiosk agent' -Action $aa -Trigger $at -Principal $ap -Settings $set -Force | Out-Null
Start-ScheduledTask -TaskName 'ctrl32 kiosk agent'
$signedIn = (Get-CimInstance Win32_ComputerSystem).UserName
if ($signedIn -like "*\$KioskUser") { Start-ScheduledTask -TaskName 'ctrl32 kiosk launcher'; Write-Host "the launcher started in the session of $KioskUser" }

Step 'done'
Write-Host "Kiosk PC '__CTRL32_NAME__' is set up. In ctrl32 open Displays -> Kiosk PCs: it reports within a minute."
Write-Host "Each monitor shows a pairing code: pair them under Displays (Pair display) and link them to this PC."
Write-Host "Delete this setup file now: it carries the credential of this PC."
if (-not $NoReboot -and -not ($signedIn -like "*\$KioskUser")) {
    Write-Host "Restart the PC to sign in as $KioskUser automatically: Restart-Computer"
}
